(334532, 25480, 8953, '<td valign="top">this was an 9 for me.</td>', 'this was an 9 for me.', '2003-06-22 01:19:25.000000', NULL, 1),
(334534, 25463, 8953, '<td valign="top">If your number changed its because I came back through after reading and understanding more of how to do this and also I re-set my monitor. yours looks much better.8</td>', 'If your number changed its because I came back through after reading and understanding more of how to do this and also I re-set my monitor. yours looks much better.8', '2003-06-22 01:22:19.000000', NULL, 1),
