(334549, 25433, 8953, '<td valign="top">lots of emotion...I like! thanks 8</td>', 'lots of emotion...I like! thanks 8', '2003-06-22 01:28:37.000000', NULL, 1),
(334550, 25561, 8953, '<td valign="top">spooky good job! 8</td>', 'spooky good job! 8', '2003-06-22 01:29:31.000000', NULL, 1),
(334553, 24960, 8953, '<td valign="top">Like mine yours seems bright. But unlike mine. it seems to work 8</td>', 'Like mine yours seems bright. But unlike mine. it seems to work 8', '2003-06-22 01:31:52.000000', NULL, 1),
(334555, 25135, 8953, '<td valign="top">adjusting my screen made this work for me I had you at a lower number but made another pass....I spent some time reading forums and feel a lot of us got tagged for issues out of our hands...anyway nice job! 8</td>', 'adjusting my screen made this work for me I had you at a lower number but made another pass....I spent some time reading forums and feel a lot of us got tagged for issues out of our hands...anyway nice job! 8', '2003-06-22 01:36:53.000000', NULL, 1),
(334557, 25518, 8953, '<td valign="top">adjusted screen...adjusting Vote up a couple more. 9</td>', 'adjusted screen...adjusting Vote up a couple more. 9', '2003-06-22 01:38:19.000000', NULL, 1),
(334570, 25260, 6771, '<td valign="top">great sharpness and detail in the dark areas.  I am familiar with this, being an ER RN. Nice shot 8</td>', 'great sharpness and detail in the dark areas.  I am familiar with this, being an ER RN. Nice shot 8', '2003-06-22 03:09:45.000000', NULL, 1),
(334572, 25559, 6771, '<td valign="top">great detail in the lit areas.  and then fading back.  one of my favs 8<br/></td>', 'great detail in the lit areas.  and then fading back.  one of my favs 8', '2003-06-22 03:10:52.000000', NULL, 1),
(334573, 24822, 6771, '<td valign="top">I really love this image.  excellent detail throughout the shot, but still low key in my opinion  8</td>', 'I really love this image.  excellent detail throughout the shot, but still low key in my opinion  8', '2003-06-22 03:11:40.000000', NULL, 1),
(334574, 25471, 6771, '<td valign="top">Nice low key shot dimitry.   (C:  able to catch detail in the dark areas   7</td>', 'Nice low key shot dimitry.   (C:  able to catch detail in the dark areas   7', '2003-06-22 03:12:28.000000', NULL, 1),
(334577, 25436, 6771, '<td valign="top">Very interesting photo.  Great technique. 7</td>', 'Very interesting photo.  Great technique. 7', '2003-06-22 03:34:27.000000', NULL, 1),
(334578, 25514, 6771, '<td valign="top">Looks like locorice whips all twisted together.  Can see good detail in the shadow areas.  7</td>', 'Looks like locorice whips all twisted together.  Can see good detail in the shadow areas.  7', '2003-06-22 03:35:14.000000', NULL, 1),
(334579, 25241, 6771, '<td valign="top">I really like this photo.  I would rather not see the incense stick and just take it from the smoke and the familiar looking pattern.  7</td>', 'I really like this photo.  I would rather not see the incense stick and just take it from the smoke and the familiar looking pattern.  7', '2003-06-22 03:38:43.000000', NULL, 1),
(334583, 24850, 6870, '<td valign="top">I love the way the finger on one hand is dark and the other is light, and vice versa for the other fingers. I like!</td>', 'I love the way the finger on one hand is dark and the other is light, and vice versa for the other fingers. I like!', '2003-06-22 03:58:15.000000', NULL, 1),
(334584, 25428, 6870, '<td valign="top">At first I didn''t feel this met the challenge, but now, what the heck, it''s dark, right? And I just love this shot: composition, focus especially. Nice work. 9</td>', 'At first I didn''t feel this met the challenge, but now, what the heck, it''s dark, right? And I just love this shot: composition, focus especially. Nice work. 9', '2003-06-22 03:59:27.000000', NULL, 1),
(334586, 25358, 6870, '<td valign="top">Dark and foreboding! That''s for sure! I love the green and the breath and wish the face were just a tiny bit more in focus. I can''t see a reason for it not to be. Still, nice work on most fronts!</td>', 'Dark and foreboding! That''s for sure! I love the green and the breath and wish the face were just a tiny bit more in focus. I can''t see a reason for it not to be. Still, nice work on most fronts!', '2003-06-22 04:00:48.000000', NULL, 1),
(334587, 25386, 6870, '<td valign="top">This is a really interesting view--almost a candid shot. I like the realism implied by capturing the many lines and shapes that seem quite random. The window at lower left is a good touch, I feel.</td>', 'This is a really interesting view--almost a candid shot. I like the realism implied by capturing the many lines and shapes that seem quite random. The window at lower left is a good touch, I feel.', '2003-06-22 04:02:32.000000', NULL, 1),
(334588, 25473, 6870, '<td valign="top">Even your whites seem dark. Nice! Loving eyes, but also very pretty eyes. I like the intense feel the low key lighting gives.</td>', 'Even your whites seem dark. Nice! Loving eyes, but also very pretty eyes. I like the intense feel the low key lighting gives.', '2003-06-22 04:03:28.000000', NULL, 1),
(334589, 24766, 6870, '<td valign="top">Wow, their school must have lost the game for sure! Low light gives this photo an appropriate emotive quality. 9</td>', 'Wow, their school must have lost the game for sure! Low light gives this photo an appropriate emotive quality. 9', '2003-06-22 04:04:38.000000', NULL, 1),
(334590, 25450, 6870, '<td valign="top">IN this low light, I love how the hematite looks the same tone as the pearls! This is a nice stock photo, but I wish the jewels were just a tad more in focus. Nice.</td>', 'IN this low light, I love how the hematite looks the same tone as the pearls! This is a nice stock photo, but I wish the jewels were just a tad more in focus. Nice.', '2003-06-22 04:06:01.000000', NULL, 1),
(334591, 25030, 6870, '<td valign="top">Low key lighting gives this lovely skin a real lustre that is difficult to describe. Composition is marvelous. Title lacks imagination in my view, though it is certainly accurate!</td>', 'Low key lighting gives this lovely skin a real lustre that is difficult to describe. Composition is marvelous. Title lacks imagination in my view, though it is certainly accurate!', '2003-06-22 04:07:38.000000', NULL, 1),
(334592, 24967, 6870, '<td valign="top">The lighting makes each of these objects glow by themselves it seems. Depth of field works, but title implies that all are important, so maybe experiment with all being in focus? Nice work, nonetheless.</td>', 'The lighting makes each of these objects glow by themselves it seems. Depth of field works, but title implies that all are important, so maybe experiment with all being in focus? Nice work, nonetheless.', '2003-06-22 04:09:01.000000', NULL, 1),
(334594, 25564, 6870, '<td valign="top">This lighting makes this statue certainly have dimension. I find giggling and the dark tones somehow incompatible, so I question your title. To me, the statue seems more in shock of some tragic events. I love the tones and composition. Nice work.</td>', 'This lighting makes this statue certainly have dimension. I find giggling and the dark tones somehow incompatible, so I question your title. To me, the statue seems more in shock of some tragic events. I love the tones and composition. Nice work.', '2003-06-22 04:11:05.000000', NULL, 1),
(334595, 25440, 5585, '<td valign="top">so interesting...</td>', 'so interesting...', '2003-06-22 04:41:39.000000', NULL, 1),
(334596, 25428, 5585, '<td valign="top">good DOF...</td>', 'good DOF...', '2003-06-22 04:48:06.000000', NULL, 1),
(334597, 25520, 5585, '<td valign="top">I think this met the challenge...border maybe overdone.... but....a good photo....</td>', 'I think this met the challenge...border maybe overdone.... but....a good photo....', '2003-06-22 04:52:13.000000', NULL, 1),
(334598, 24822, 5585, '<td valign="top">very nice pic..actually very dark.... good representation</td>', 'very nice pic..actually very dark.... good representation', '2003-06-22 04:53:33.000000', NULL, 1);
