(338389, 25528, 1717, '<td valign="top">wonderful shot!  great lighting and textures.  good job!</td>', 'wonderful shot!  great lighting and textures.  good job!', '2003-06-25 21:28:09.000000', NULL, 1),
(338392, 25480, 9604, '<td valign="top">Truely black on black.... great shot!</td>', 'Truely black on black.... great shot!', '2003-06-25 21:28:39.000000', NULL, 1),
(338394, 24819, 7628, '<td valign="top">I like the way the light just catches the buttons - just enough for us to see what they are.  That is my idea of black on black.  Your composition is a bit difuse - my eye keeps popping over to the thumb-stick on the left expecting to see more.  I guess I''d like to incluse more of the controller, and have a greater DOF.</td>', 'I like the way the light just catches the buttons - just enough for us to see what they are.  That is my idea of black on black.  Your composition is a bit difuse - my eye keeps popping over to the thumb-stick on the left expecting to see more.  I guess I''d like to incluse more of the controller, and have a greater DOF.', '2003-06-25 21:29:03.000000', NULL, 1),
(338401, 25564, 9604, '<td valign="top">Love the subject...Just a bit light in the lower left corner</td>', 'Love the subject...Just a bit light in the lower left corner', '2003-06-25 21:31:24.000000', NULL, 1),
(338403, 25087, 7628, '<td valign="top">What a lovely nose and mouth - the light gives them a quiet sense of shape and texure.  I do not like how blurry it is.  I suppose you wouldn''t want such a gentle subject to be harshly focussed, but this is not enough.</td>', 'What a lovely nose and mouth - the light gives them a quiet sense of shape and texure.  I do not like how blurry it is.  I suppose you wouldn''t want such a gentle subject to be harshly focussed, but this is not enough.', '2003-06-25 21:32:12.000000', NULL, 1),
(338404, 25574, 9604, '<td valign="top">Great texture and detail</td>', 'Great texture and detail', '2003-06-25 21:33:16.000000', NULL, 1),
(338406, 24822, 9604, '<td valign="top">Interesting composition and subject.</td>', 'Interesting composition and subject.', '2003-06-25 21:34:33.000000', NULL, 1),
(338409, 25495, 9604, '<td valign="top">Good subject....just enough light from the right angle to show wonderful texture!</td>', 'Good subject....just enough light from the right angle to show wonderful texture!', '2003-06-25 21:36:27.000000', NULL, 1),
(338411, 25440, 9604, '<td valign="top">It sure is "black on black".  I think maybe we need a bit more light!</td>', 'It sure is "black on black".  I think maybe we need a bit more light!', '2003-06-25 21:39:56.000000', NULL, 1),
(338415, 25565, 9604, '<td valign="top">Interesting texture, pattern and focus!</td>', 'Interesting texture, pattern and focus!', '2003-06-25 21:41:34.000000', NULL, 1),
(338417, 25480, 1717, '<td valign="top">great pic!  lighting is wonderful and i like the line that the lace makes.  good job!</td>', 'great pic!  lighting is wonderful and i like the line that the lace makes.  good job!', '2003-06-25 21:42:51.000000', NULL, 1),
(338419, 25174, 9604, '<td valign="top">Good architectural shot. Good lighting. Love the composition.</td>', 'Good architectural shot. Good lighting. Love the composition.', '2003-06-25 21:45:39.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(338426, 25436, 9604, '<td valign="top">Great light range range from light to dark.</td>', 'Great light range range from light to dark.', '2003-06-25 21:47:51.000000', NULL, 1),
(338430, 24888, 9604, '<td valign="top">Goog job for a tough challenge!</td>', 'Goog job for a tough challenge!', '2003-06-25 21:50:37.000000', NULL, 1),
(338431, 25471, 1368, '<td valign="top">Great picture and great framing! I would have given it a 10 if I could vote. But someone might vote it lower cause of the pubic hairs ...</td>', 'Great picture and great framing! I would have given it a 10 if I could vote. But someone might vote it lower cause of the pubic hairs ...', '2003-06-25 21:51:13.000000', NULL, 1),
(338432, 25563, 9604, '<td valign="top">Good lighting, good subject.  Might have backed off a bit to include more of the subject.</td>', 'Good lighting, good subject.  Might have backed off a bit to include more of the subject.', '2003-06-25 21:52:39.000000', NULL, 1),
(338436, 25470, 9604, '<td valign="top">Good macro shot...good detail and texture!</td>', 'Good macro shot...good detail and texture!', '2003-06-25 21:53:43.000000', NULL, 1),
(338439, 25514, 9604, '<td valign="top">Great texture and pattern for a tough challenge!</td>', 'Great texture and pattern for a tough challenge!', '2003-06-25 21:55:26.000000', NULL, 1),
(338440, 24770, 9604, '<td valign="top">Love the composition!  The little splash of color really "makes" this shot!</td>', 'Love the composition!  The little splash of color really "makes" this shot!', '2003-06-25 21:56:48.000000', NULL, 1),
(338443, 24855, 9604, '<td valign="top">Unbelievable depth of field for this low key shot.</td>', 'Unbelievable depth of field for this low key shot.', '2003-06-25 21:57:57.000000', NULL, 1),
(338452, 24983, 1054, '<td valign="top">The smoke curl on this shot is outstanding.</td>', 'The smoke curl on this shot is outstanding.', '2003-06-25 22:03:25.000000', NULL, 1),
(338475, 24888, 6870, '<td valign="top">The lighting here certainly makes these lovers look mysterious! Good subject. I''m not sure the source of the light is from the best direction; somehow it looks awkward...</td>', 'The lighting here certainly makes these lovers look mysterious! Good subject. I''m not sure the source of the light is from the best direction; somehow it looks awkward...', '2003-06-25 22:52:14.000000', NULL, 1),
(338477, 24908, 6870, '<td valign="top">The black background really does help the watch pop out a bit more. Perhaps a different angle/point of view would help in make the watch seem more . . . special. Nice tones and levels here.</td>', 'The black background really does help the watch pop out a bit more. Perhaps a different angle/point of view would help in make the watch seem more . . . special. Nice tones and levels here.', '2003-06-25 22:53:29.000000', NULL, 1),
(338478, 25070, 6870, '<td valign="top">Nice use of negative space here, and lighting is nice from that direction. It certainly looks formal and austere.</td>', 'Nice use of negative space here, and lighting is nice from that direction. It certainly looks formal and austere.', '2003-06-25 22:54:24.000000', NULL, 1),
(338479, 25300, 6870, '<td valign="top">The lighting adds depth to this object, but the dark tones curiously do not add much emotional impact for me. Perhaps a different point of view would help. Still, nicely done.</td>', 'The lighting adds depth to this object, but the dark tones curiously do not add much emotional impact for me. Perhaps a different point of view would help. Still, nicely done.', '2003-06-25 22:55:36.000000', NULL, 1),
(338480, 25206, 6870, '<td valign="top">I really like these dark tones and the subtle colors.</td>', 'I really like these dark tones and the subtle colors.', '2003-06-25 22:56:27.000000', NULL, 1),
(338481, 25463, 6870, '<td valign="top">The directional light adds depth to the texture, which is good! You''ve also found some interesting pattern variations to show us.</td>', 'The directional light adds depth to the texture, which is good! You''ve also found some interesting pattern variations to show us.', '2003-06-25 22:57:34.000000', NULL, 1),
(338482, 25563, 6870, '<td valign="top">Slightly off center works well here; I like how it suggests here that the shoes go onward and are part of an environment that we can''t see. Here''s a dumb comment, but I wish the shoes were older or had more character to make them more intresting. Nice work anyway.</td>', 'Slightly off center works well here; I like how it suggests here that the shoes go onward and are part of an environment that we can''t see. Here''s a dumb comment, but I wish the shoes were older or had more character to make them more intresting. Nice work anyway.', '2003-06-25 22:59:18.000000', NULL, 1),
(338484, 25198, 6870, '<td valign="top">Engaging photograph! use of light and low key work pretty well here, though I can see this shot being taken in a lighter context, too. The darkness, oddly, does not add much emotional impact.</td>', 'Engaging photograph! use of light and low key work pretty well here, though I can see this shot being taken in a lighter context, too. The darkness, oddly, does not add much emotional impact.', '2003-06-25 23:00:28.000000', NULL, 1),
(338485, 25520, 6870, '<td valign="top">I like the directional lighting, and the dark tones beef up the mysterious nature of the image.</td>', 'I like the directional lighting, and the dark tones beef up the mysterious nature of the image.', '2003-06-25 23:01:02.000000', NULL, 1),
(338487, 24983, 6870, '<td valign="top">Darn right. The dark tones here do add a sense of danger and ominousness to your subject.</td>', 'Darn right. The dark tones here do add a sense of danger and ominousness to your subject.', '2003-06-25 23:01:56.000000', NULL, 1),
(338489, 25530, 6870, '<td valign="top">I like how the lighting here is just enough to reveal your subject! Oddly, the dark tones do not add  much emotional impact, perhaps because the point of view is so "normal."</td>', 'I like how the lighting here is just enough to reveal your subject! Oddly, the dark tones do not add  much emotional impact, perhaps because the point of view is so "normal."', '2003-06-25 23:02:58.000000', NULL, 1),
(338491, 25036, 6870, '<td valign="top">This reminds me of the Matrix! Cute couple, and the darkness adds a sense of danger to them.</td>', 'This reminds me of the Matrix! Cute couple, and the darkness adds a sense of danger to them.', '2003-06-25 23:03:49.000000', NULL, 1),
(338493, 24841, 6870, '<td valign="top">Some might not call this low key, but I think it''s pretty dark, or dark enough, anyway. The brightest parts, however, do steal the attention away from the bridge, whose sillouette I do not find all that interesting, though it makes a good background for the engaging clouds and light.</td>', 'Some might not call this low key, but I think it''s pretty dark, or dark enough, anyway. The brightest parts, however, do steal the attention away from the bridge, whose sillouette I do not find all that interesting, though it makes a good background for the engaging clouds and light.', '2003-06-25 23:05:36.000000', NULL, 1),
(338494, 25260, 6870, '<td valign="top">I initially like this shot a lot. The edge of the blade is well defined and interesting. I''m not sure what it''s cutting. It looks like skin, but it has weird lumps and wrinkles, so I''m just slightly unclear as to what is going on.</td>', 'I initially like this shot a lot. The edge of the blade is well defined and interesting. I''m not sure what it''s cutting. It looks like skin, but it has weird lumps and wrinkles, so I''m just slightly unclear as to what is going on.', '2003-06-25 23:07:24.000000', NULL, 1),
(338495, 24855, 6870, '<td valign="top">This makes a  unique abstract, but enough is in detail that I want to know exactly what''s going on. I''m not sure how I should feel about burnt food bits left in a pan. To me, it''s not quite interesting in and of itself, yet no real story is suggested by either the photo or its title.</td>', 'This makes a  unique abstract, but enough is in detail that I want to know exactly what''s going on. I''m not sure how I should feel about burnt food bits left in a pan. To me, it''s not quite interesting in and of itself, yet no real story is suggested by either the photo or its title.', '2003-06-25 23:09:34.000000', NULL, 1),
(338496, 24770, 6870, '<td valign="top">the lighting really adds dimension and depth to this cherub. The dark tones also add a sense of loneliness or sadness to the image. I also like the addition of the tree to help frame this shot.</td>', 'the lighting really adds dimension and depth to this cherub. The dark tones also add a sense of loneliness or sadness to the image. I also like the addition of the tree to help frame this shot.', '2003-06-25 23:10:50.000000', NULL, 1),
(338498, 25480, 6870, '<td valign="top">Your lighting certainly gives the shoe some dimension and depth. The darker tones don''t really add any emotional quality to the shot--only a bit of formality. Perhaps a different point of view would add some drama.</td>', 'Your lighting certainly gives the shoe some dimension and depth. The darker tones don''t really add any emotional quality to the shot--only a bit of formality. Perhaps a different point of view would add some drama.', '2003-06-25 23:12:25.000000', NULL, 1),
(338500, 25518, 6870, '<td valign="top">This takes a second to click in to what it is. I like how the dark tones suggest Soul. perhaps a different point of view would clue us in more that this is a sax--including more keys, for instance, or just panning a little wider?</td>', 'This takes a second to click in to what it is. I like how the dark tones suggest Soul. perhaps a different point of view would clue us in more that this is a sax--including more keys, for instance, or just panning a little wider?', '2003-06-25 23:13:48.000000', NULL, 1),
(338889, 25070, 7628, '<td valign="top">This is great - how little light it takes to suggest "egg" I like the touch of highlight onthe top of the egg and the rim on the left side of the cup.  I''d like to see how it loooks with a bit of light to suggest the base. 8</td>', 'This is great - how little light it takes to suggest "egg" I like the touch of highlight onthe top of the egg and the rim on the left side of the cup.  I''d like to see how it loooks with a bit of light to suggest the base. 8', '2003-06-26 08:30:29.000000', NULL, 1),
(338939, 24893, 7570, '<td valign="top">very beautiful picture and sets the mood of a quiet evening. I like the serenity captured in this image. Too bad I cant vote, or this will definately get a 9 from me. watch out for the pink specson the lower part of the photo though. great work</td>', 'very beautiful picture and sets the mood of a quiet evening. I like the serenity captured in this image. Too bad I cant vote, or this will definately get a 9 from me. watch out for the pink specson the lower part of the photo though. great work', '2003-06-26 10:15:25.000000', NULL, 1),
(338945, 25126, 6761, '<td valign="top">Very nice</td>', 'Very nice', '2003-06-26 10:22:07.000000', NULL, 1),
(338972, 24983, 6761, '<td valign="top">Really nice shot. It allmost looks like the smoke is beeing poured down instead of floating up</td>', 'Really nice shot. It allmost looks like the smoke is beeing poured down instead of floating up', '2003-06-26 11:07:43.000000', NULL, 1),
(338975, 25436, 6761, '<td valign="top">Very very nice.</td>', 'Very very nice.', '2003-06-26 11:09:35.000000', NULL, 1),
(338976, 25566, 6761, '<td valign="top">What, exactly, is the "black on black" on this one?</td>', 'What, exactly, is the "black on black" on this one?', '2003-06-26 11:10:51.000000', NULL, 1),
(339004, 25429, 6870, '<td valign="top">For the longest time, I didn''t know what this was--a helmet, right? The lighting gives this a very formal look, as if it were in a museum. You also reveal just enough of it to give it depth. As an unfamiliar object, to me anyway, a different point of view or title might be helpful.</td>', 'For the longest time, I didn''t know what this was--a helmet, right? The lighting gives this a very formal look, as if it were in a museum. You also reveal just enough of it to give it depth. As an unfamiliar object, to me anyway, a different point of view or title might be helpful.', '2003-06-26 12:13:07.000000', NULL, 1),
(339007, 24688, 6870, '<td valign="top">Sound challenge revisited! I like the perspective here and point of view making the circles get smaller--or exaggerating this effect.</td>', 'Sound challenge revisited! I like the perspective here and point of view making the circles get smaller--or exaggerating this effect.', '2003-06-26 12:14:05.000000', NULL, 1),
(339010, 25422, 6870, '<td valign="top">The low key effect, combined with your lighting, makes her look angry or discontent. I like the direction of the light, and you could be even darker if you wanted and perhaps add even more mood.</td>', 'The low key effect, combined with your lighting, makes her look angry or discontent. I like the direction of the light, and you could be even darker if you wanted and perhaps add even more mood.', '2003-06-26 12:15:30.000000', NULL, 1),
(339011, 25368, 6870, '<td valign="top">The low key adds a definite sombre mood to this portrait, so I think it is successful.</td>', 'The low key adds a definite sombre mood to this portrait, so I think it is successful.', '2003-06-26 12:16:31.000000', NULL, 1),
(339013, 25440, 4400, '<td valign="top">My computer monitor is not bad, but I can hardly see the baby 5pt</td>', 'My computer monitor is not bad, but I can hardly see the baby 5pt', '2003-06-26 12:17:16.000000', NULL, 1),
(339016, 24995, 6870, '<td valign="top">The darkness and your composition really make this candle feel isolated in vast blackness. Nice work. I do wish that more were in focus here, though.</td>', 'The darkness and your composition really make this candle feel isolated in vast blackness. Nice work. I do wish that more were in focus here, though.', '2003-06-26 12:18:27.000000', NULL, 1),
(339021, 24957, 6870, '<td valign="top">I like the direction from which the light is coming. The low key effect, combined with her expression, create a sense of mystery and exotic-ness.</td>', 'I like the direction from which the light is coming. The low key effect, combined with her expression, create a sense of mystery and exotic-ness.', '2003-06-26 12:20:09.000000', NULL, 1),
(339024, 25433, 6870, '<td valign="top">I really like the lighting here, especially its direction. The low key effect and his expression and stance makes me feel as if he will NEVER get to the major leagues--I hope that was your intention!</td>', 'I really like the lighting here, especially its direction. The low key effect and his expression and stance makes me feel as if he will NEVER get to the major leagues--I hope that was your intention!', '2003-06-26 12:21:20.000000', NULL, 1),
(339026, 25578, 6870, '<td valign="top">This may be TOO low key, as there is not enough here to let us know what this is, except your title. I do like how the lights form a foundation for your image, and begin to frame it.</td>', 'This may be TOO low key, as there is not enough here to let us know what this is, except your title. I do like how the lights form a foundation for your image, and begin to frame it.', '2003-06-26 12:22:42.000000', NULL, 1),
(339029, 25472, 6870, '<td valign="top">I''m looking for the grace.....<br/> <br/>I really like the various textures here, made darkly nostalgic (bad, unavoidable memories) by the low key lighting. Brave of you to choose light subjects for this challenge!</td>', 'I''m looking for the grace..... I really like the various textures here, made darkly nostalgic (bad, unavoidable memories) by the low key lighting. Brave of you to choose light subjects for this challenge!', '2003-06-26 12:24:33.000000', NULL, 1),
(339031, 25062, 6870, '<td valign="top">The lighting is just right here, giving the jacks definition and depth and dimension. I would think that they should be in sharp focus, though.</td>', 'The lighting is just right here, giving the jacks definition and depth and dimension. I would think that they should be in sharp focus, though.', '2003-06-26 12:25:53.000000', NULL, 1),
(339060, 25450, 3724, '<td valign="top">.<br/>   . <br/>       .<br/>            .<br/>                  ..........my favorite of the challenge..........</td>', '.   .        .            .                  ..........my favorite of the challenge..........', '2003-06-26 13:11:41.000000', NULL, 1),
(339075, 25470, 3724, '<td valign="top">......a lot of shoes have been shown lately.  Certianly a good stilllife subject....  and this is one of the best I have seen.  I enjoy the fine detail, clear and sharp.  You have brought the mundane subject to life with good composition.  I like the crop that shows a tilted, jaunty angle of the shoe, which imparts what a shoe is really like........   something that conforms to what is inside it!  I enjoy the pic, good job.</td>', '......a lot of shoes have been shown lately.  Certianly a good stilllife subject....  and this is one of the best I have seen.  I enjoy the fine detail, clear and sharp.  You have brought the mundane subject to life with good composition.  I like the crop that shows a tilted, jaunty angle of the shoe, which imparts what a shoe is really like........   something that conforms to what is inside it!  I enjoy the pic, good job.', '2003-06-26 13:23:13.000000', NULL, 1),
(339094, 25436, 3724, '<td valign="top">.....bold subject matter .......  slippery and shiny....  appreciate the definition in space, which could have been lost with less awareness and sensitivity of the background.......   The subtle frame works perfect with the image.</td>', '.....bold subject matter .......  slippery and shiny....  appreciate the definition in space, which could have been lost with less awareness and sensitivity of the background.......   The subtle frame works perfect with the image.', '2003-06-26 13:37:50.000000', NULL, 1),
(339104, 24946, 3724, '<td valign="top">like the soft intermittent pencil line frame a lot......  organic image is interesting and i rate this picture 7 or 8......</td>', 'like the soft intermittent pencil line frame a lot......  organic image is interesting and i rate this picture 7 or 8......', '2003-06-26 13:41:37.000000', NULL, 1),
(339110, 25563, 3724, '<td valign="top">shoes........   I like the off center composition, an interesting take and good work</td>', 'shoes........   I like the off center composition, an interesting take and good work', '2003-06-26 13:44:23.000000', NULL, 1),
(339130, 25421, 3724, '<td valign="top">like your use of some colour in this challenge......  lighting is supurb.....  I am seeing three lights used?  or is it just two?  main and hair lite? The disintegration of the pupil and iris of eye into shadow to me hurts the image a little.  But I still like the portrait a lot.</td>', 'like your use of some colour in this challenge......  lighting is supurb.....  I am seeing three lights used?  or is it just two?  main and hair lite? The disintegration of the pupil and iris of eye into shadow to me hurts the image a little.  But I still like the portrait a lot.', '2003-06-26 13:53:10.000000', NULL, 1),
(339182, 25333, 6870, '<td valign="top">In this image, I see a hat, but I''m not sure what I"m supposed to think after this. It''s just a hat in a dark shot with little emotive quality. Perhaps a different point of view would help add to the drama or enhance the mood. I do like how you''ve used light to give shape to the hat in very subtle ways.</td>', 'In this image, I see a hat, but I''m not sure what I"m supposed to think after this. It''s just a hat in a dark shot with little emotive quality. Perhaps a different point of view would help add to the drama or enhance the mood. I do like how you''ve used light to give shape to the hat in very subtle ways.', '2003-06-26 14:47:56.000000', NULL, 1),
(339186, 24927, 6870, '<td valign="top">I like your composition here. The clock in the lower left seems to introduce the void behind it and combined with the low key and potentially ominous title, suggests that the void is filled with mysterious things. The shadow on the face of the clock distracts me just a tad, perhaps because of the harsh shadow? Nice work.</td>', 'I like your composition here. The clock in the lower left seems to introduce the void behind it and combined with the low key and potentially ominous title, suggests that the void is filled with mysterious things. The shadow on the face of the clock distracts me just a tad, perhaps because of the harsh shadow? Nice work.', '2003-06-26 14:50:28.000000', NULL, 1),
(339187, 25561, 6870, '<td valign="top">A black cat in a black night! I do like how the eyes shine in all of that darkness? I kind of wish that I could see just a tad more definition on the cat--not a lot, but enough to suggest a few body parts, like it is on the face. Nice work.</td>', 'A black cat in a black night! I do like how the eyes shine in all of that darkness? I kind of wish that I could see just a tad more definition on the cat--not a lot, but enough to suggest a few body parts, like it is on the face. Nice work.', '2003-06-26 14:51:59.000000', NULL, 1),
(339188, 24878, 6870, '<td valign="top">I really enjoy this photograph. The photo says what the title says, so I find the title very appropriate. The dark tones and directional lighting work well together here, as does your composition. 9</td>', 'I really enjoy this photograph. The photo says what the title says, so I find the title very appropriate. The dark tones and directional lighting work well together here, as does your composition. 9', '2003-06-26 14:53:06.000000', NULL, 1),
(339190, 25566, 6870, '<td valign="top">I just really enjoy this photograph and how you''ve been able to negotiate light so that the flower is lit, but that the photo has an overall dark quality. I''m sure some have suggested that the photo may be too bright, and I agree, but only to a small extent. I still think this is low key and well done.</td>', 'I just really enjoy this photograph and how you''ve been able to negotiate light so that the flower is lit, but that the photo has an overall dark quality. I''m sure some have suggested that the photo may be too bright, and I agree, but only to a small extent. I still think this is low key and well done.', '2003-06-26 14:55:16.000000', NULL, 1),
(339191, 25466, 6870, '<td valign="top">You''ve made a graphic image out of this photo, and I don''t mind that so much, though I''msure that some do mind. I do enjoy the lighting and especially the arrangement of the objects in the frame, added to excellent cropping. The low key lighting makes these every day objects seem mysterious in a technology sense, as these are the images that fill the frame.</td>', 'You''ve made a graphic image out of this photo, and I don''t mind that so much, though I''msure that some do mind. I do enjoy the lighting and especially the arrangement of the objects in the frame, added to excellent cropping. The low key lighting makes these every day objects seem mysterious in a technology sense, as these are the images that fill the frame.', '2003-06-26 14:57:17.000000', NULL, 1),
(339193, 24919, 6870, '<td valign="top">I enjoy the pose, the grain and the composition here. The low key lighting certainly brings out her dark side! Both literally and figuratively. Her expression heightens this notion.</td>', 'I enjoy the pose, the grain and the composition here. The low key lighting certainly brings out her dark side! Both literally and figuratively. Her expression heightens this notion.', '2003-06-26 14:58:29.000000', NULL, 1),
(339194, 25250, 6870, '<td valign="top">I l ike the unique idea of this still life, and find your arrangement very satisfying. The low key adds a feeling of sad nostalgia to me, as if these skills and tools and way of life are fading into the darkness of memory and history.</td>', 'I l ike the unique idea of this still life, and find your arrangement very satisfying. The low key adds a feeling of sad nostalgia to me, as if these skills and tools and way of life are fading into the darkness of memory and history.', '2003-06-26 14:59:54.000000', NULL, 1),
(339195, 25557, 6870, '<td valign="top">Wonderful composition with lots of void for the hand to help. The low key lighting adds a sense of danger. The hand could even be darker and perhaps heighten the danger further. Currently, it is brightness reaching into darkness, and that works, too.</td>', 'Wonderful composition with lots of void for the hand to help. The low key lighting adds a sense of danger. The hand could even be darker and perhaps heighten the danger further. Currently, it is brightness reaching into darkness, and that works, too.', '2003-06-26 15:01:44.000000', NULL, 1),
(339196, 24891, 6870, '<td valign="top">The low key lighting here heightens the exotic feel of this doll. The direction the light comes from is very nice and helps to define the doll into three dimensions. Very effective composition. Some may claim that it''s not dark enough, but I find it low key and engaging.</td>', 'The low key lighting here heightens the exotic feel of this doll. The direction the light comes from is very nice and helps to define the doll into three dimensions. Very effective composition. Some may claim that it''s not dark enough, but I find it low key and engaging.', '2003-06-26 15:03:40.000000', NULL, 1),
(339198, 25455, 6870, '<td valign="top">Certainly low key, and the glass is placed nicely in the frame for interest. I don''t find the low key doing anything to this glass, though. I don''t find the mood or emotional content assisted. I like how just enough light is used to define the glass as a glass.</td>', 'Certainly low key, and the glass is placed nicely in the frame for interest. I don''t find the low key doing anything to this glass, though. I don''t find the mood or emotional content assisted. I like how just enough light is used to define the glass as a glass.', '2003-06-26 15:05:25.000000', NULL, 1),
(339200, 25135, 6870, '<td valign="top">The lighting you do have here defines the holes of the object, but I''m still not sure what it is. Perhaps it''s too low key! Oh well. Maybe a wisp of smoke would help? The off center composition seems effective at helping this object appear to be in a larger space.</td>', 'The lighting you do have here defines the holes of the object, but I''m still not sure what it is. Perhaps it''s too low key! Oh well. Maybe a wisp of smoke would help? The off center composition seems effective at helping this object appear to be in a larger space.', '2003-06-26 15:07:34.000000', NULL, 1),
(339202, 24730, 6870, '<td valign="top">Low key lighting does add a bit of mystery to this object, as it seems very technology oriented, but I''m not sure what it is?</td>', 'Low key lighting does add a bit of mystery to this object, as it seems very technology oriented, but I''m not sure what it is?', '2003-06-26 15:08:57.000000', NULL, 1),
(339204, 24819, 6870, '<td valign="top">Ominous title with the low key lighting! This appears to be a game controller of some kind? The lighting gives it definition and mood, but then it''s a game controller, so the two don''t quite match for me. Composition is interesting and suggests that this object is part of a larger environment.</td>', 'Ominous title with the low key lighting! This appears to be a game controller of some kind? The lighting gives it definition and mood, but then it''s a game controller, so the two don''t quite match for me. Composition is interesting and suggests that this object is part of a larger environment.', '2003-06-26 15:11:02.000000', NULL, 1),
(339205, 25522, 6870, '<td valign="top">I like how the lighting makes the eyes shine and how it serves to subtly define the cat''s body. Oddly, the low key lighting doesn''t create or heighten the tone or mood of the photograph. Perhaps a different perspective or point of view would help.</td>', 'I like how the lighting makes the eyes shine and how it serves to subtly define the cat''s body. Oddly, the low key lighting doesn''t create or heighten the tone or mood of the photograph. Perhaps a different perspective or point of view would help.', '2003-06-26 15:12:36.000000', NULL, 1),
(339331, 25436, 5475, '<td valign="top">What an interesting mage!  At first I thought this was a statue or figurine, but I think it is a real person.  Tell me if I''m wrong!!  I''ll be 38 on Tuesday, so I''m kind of out of the fashion loop.  I haven''t seen clothes like this where I buy my Levi''s and button downs!  LOL  Great pose, lighting is excellent, meets the challenge well.  The areas that are blown out are a plus for this image due to the material/plastic the suit is made out of.    I''ve never known anyone who actually  knows a real super hero.  Once the challenge is over, could I get an autograph???  Electronic autograph is fine...  jdanderson1002@cs.com<br/>Wonderful creativity and execution.  I have to give it a 10, even though that will diminish my chances of getting a top 3!!<br/>(PS  looks like one of magnetics'' shots!)</td>', 'What an interesting mage!  At first I thought this was a statue or figurine, but I think it is a real person.  Tell me if I''m wrong!!  I''ll be 38 on Tuesday, so I''m kind of out of the fashion loop.  I haven''t seen clothes like this where I buy my Levi''s and button downs!  LOL  Great pose, lighting is excellent, meets the challenge well.  The areas that are blown out are a plus for this image due to the material/plastic the suit is made out of.    I''ve never known anyone who actually  knows a real super hero.  Once the challenge is over, could I get an autograph???  Electronic autograph is fine...  jdanderson1002@cs.comWonderful creativity and execution.  I have to give it a 10, even though that will diminish my chances of getting a top 3!!(PS  looks like one of magnetics'' shots!)', '2003-06-26 18:16:07.000000', NULL, 1),
(339362, 24919, 6771, '<td valign="top">I think you got great lighting and detail in the darker areas, but it came out rather grainy throughout the photo.  Some noise reduction can make this into a very good portrait</td>', 'I think you got great lighting and detail in the darker areas, but it came out rather grainy throughout the photo.  Some noise reduction can make this into a very good portrait', '2003-06-26 18:33:24.000000', NULL, 1),
(339363, 25561, 6771, '<td valign="top">Defitnitely is "black on black."  but I would like to see the low key aspect play into it more and have some detail seen.  Such as being able to see some detail of the fur</td>', 'Defitnitely is "black on black."  but I would like to see the low key aspect play into it more and have some detail seen.  Such as being able to see some detail of the fur', '2003-06-26 18:34:42.000000', NULL, 1),
(339364, 25062, 6771, '<td valign="top">This would be exceptional photo if it were in better focus.  Good detail in the darker areas and I like the light reflections</td>', 'This would be exceptional photo if it were in better focus.  Good detail in the darker areas and I like the light reflections', '2003-06-26 18:35:52.000000', NULL, 1),
(339366, 25250, 6771, '<td valign="top">I like this set up, but cannot get myself to call it a low key photo.  Seems like a black and white shot in my opinion.</td>', 'I like this set up, but cannot get myself to call it a low key photo.  Seems like a black and white shot in my opinion.', '2003-06-26 18:36:51.000000', NULL, 1),
(339367, 25473, 6771, '<td valign="top">Nice shot.  Hard for me to get myself to see this as low key though.  There is not alot of "darker" areas that qualify to me.  Is a well exposed shot though.</td>', 'Nice shot.  Hard for me to get myself to see this as low key though.  There is not alot of "darker" areas that qualify to me.  Is a well exposed shot though.', '2003-06-26 18:38:21.000000', NULL, 1),
(339370, 25566, 6771, '<td valign="top">I am thinking this is a touch more on the lowlight area than a low key photo.  The darker areas have good detail, as would a low key shot, but overall I think the lighting is too much.  Still gonna give it a 5 though</td>', 'I am thinking this is a touch more on the lowlight area than a low key photo.  The darker areas have good detail, as would a low key shot, but overall I think the lighting is too much.  Still gonna give it a 5 though', '2003-06-26 18:40:40.000000', NULL, 1),
(339371, 25447, 6771, '<td valign="top">Pretty dark.  Are there some balls in there?  I can make out something on the right, with some very interesting patterens and shapes.</td>', 'Pretty dark.  Are there some balls in there?  I can make out something on the right, with some very interesting patterens and shapes.', '2003-06-26 18:42:03.000000', NULL, 1),
(339373, 24855, 6771, '<td valign="top">I am not sure what to make of this.  Maybe a touch more light to be able to make out what it actually is.  To me it looks like a small bit of light through a very dirty window onto a floor with dirt on it</td>', 'I am not sure what to make of this.  Maybe a touch more light to be able to make out what it actually is.  To me it looks like a small bit of light through a very dirty window onto a floor with dirt on it', '2003-06-26 18:44:00.000000', NULL, 1),
(339374, 25450, 6771, '<td valign="top">Interesting.  I really like the reflectiveness of this.   I would like to be able to make out a little more detail though</td>', 'Interesting.  I really like the reflectiveness of this.   I would like to be able to make out a little more detail though', '2003-06-26 18:44:50.000000', NULL, 1),
(339376, 25087, 6771, '<td valign="top">the lighting on this is perfect and I love the angle.    I would have liked to seen this is sharper focus though (if on purpose or not).  Then be able to see good detail in the lips and the skin.</td>', 'the lighting on this is perfect and I love the angle.    I would have liked to seen this is sharper focus though (if on purpose or not).  Then be able to see good detail in the lips and the skin.', '2003-06-26 18:45:55.000000', NULL, 1),
(339380, 25579, 6771, '<td valign="top">Nice work on the lighting and exposure.  Is pretty bland.  It appears that it is a photo of a photo.  Not a lot of depth, takes away the 3d appearance.</td>', 'Nice work on the lighting and exposure.  Is pretty bland.  It appears that it is a photo of a photo.  Not a lot of depth, takes away the 3d appearance.', '2003-06-26 18:48:00.000000', NULL, 1),
(339381, 25135, 6771, '<td valign="top">I would like to see a touch more lighting on this.  I would like to be able to make out a little more of what it is around the left side.  Good detail in the area that has the "most" amount of light though</td>', 'I would like to see a touch more lighting on this.  I would like to be able to make out a little more of what it is around the left side.  Good detail in the area that has the "most" amount of light though', '2003-06-26 18:49:06.000000', NULL, 1),
(339383, 25530, 7291, '<td valign="top">The only other time I''ve seen a shot of a 602 that looked similar to this was by bod.  Love the picture, love the camera, wish I had thought of it.</td>', 'The only other time I''ve seen a shot of a 602 that looked similar to this was by bod.  Love the picture, love the camera, wish I had thought of it.', '2003-06-26 18:49:32.000000', NULL, 1),
(339384, 25358, 7291, '<td valign="top">Nice effect.  Would like to know how you accomplished it.</td>', 'Nice effect.  Would like to know how you accomplished it.', '2003-06-26 18:49:54.000000', NULL, 1),
(339385, 25569, 6771, '<td valign="top">Nice pic, but would like a touch more light to make out a bit more detail of the feather</td>', 'Nice pic, but would like a touch more light to make out a bit more detail of the feather', '2003-06-26 18:49:55.000000', NULL, 1),
(339388, 24946, 7291, '<td valign="top">WOW!  Beautiful texture.  The low key border is absolutely fanstastic.  Congrats in advanced on your ribbon.</td>', 'WOW!  Beautiful texture.  The low key border is absolutely fanstastic.  Congrats in advanced on your ribbon.', '2003-06-26 18:53:27.000000', NULL, 1),
(339389, 24878, 4055, '<td valign="top">My only favourite this week. Fantastic portrait. Perfect composition and lighting. Perhaps a little too light in some parts but still a marvelous shot.</td>', 'My only favourite this week. Fantastic portrait. Perfect composition and lighting. Perhaps a little too light in some parts but still a marvelous shot.', '2003-06-26 18:54:44.000000', NULL, 1),
(339393, 25386, 7291, '<td valign="top">that woman in her undies is a little distracting.  what exactly where you taking a picture of?  LOL!!!</td>', 'that woman in her undies is a little distracting.  what exactly where you taking a picture of?  LOL!!!', '2003-06-26 18:58:08.000000', NULL, 1),
(339396, 24983, 7291, '<td valign="top">I love the shape that the smoke takes in this image.  very mood setting.</td>', 'I love the shape that the smoke takes in this image.  very mood setting.', '2003-06-26 19:01:48.000000', NULL, 1),
(339398, 25514, 7291, '<td valign="top">Nice abstract.  What are those...Twizlerz?</td>', 'Nice abstract.  What are those...Twizlerz?', '2003-06-26 19:02:48.000000', NULL, 1),
(339400, 25436, 7291, '<td valign="top">The only person I know of with access to such outfits is the Doctor.  Great picture.  Weird.....but very cool.</td>', 'The only person I know of with access to such outfits is the Doctor.  Great picture.  Weird.....but very cool.', '2003-06-26 19:05:22.000000', NULL, 1),
(339403, 25565, 7291, '<td valign="top">Very cool shot!!!!!!  Did you use a difusser or use Photoshop for the soft focus effect.  You know what....WHO CARES!  Absolutely incredible shot. - 10<br/> <br/>P.S.  This will go on my favorites list for sure.</td>', 'Very cool shot!!!!!!  Did you use a difusser or use Photoshop for the soft focus effect.  You know what....WHO CARES!  Absolutely incredible shot. - 10 P.S.  This will go on my favorites list for sure.', '2003-06-26 19:07:06.000000', NULL, 1),
(339404, 24902, 5475, '<td valign="top">This is a  very interesting piece of ''artwork''??<br/>Is this clay, leather?  I can''t tell, only that it is an attention grabber.<br/>You have photographed this object well in the low key fashion.  I like the side lighting , with very little detail to the left side.  Your contrast from light to dark is perfect, without much in the way of gray tones.  Yet, you still have revealed a significant amount of detail in the texture.  Your focus and DOF are dead on as well.  Well done!</td>', 'This is a  very interesting piece of ''artwork''??Is this clay, leather?  I can''t tell, only that it is an attention grabber.You have photographed this object well in the low key fashion.  I like the side lighting , with very little detail to the left side.  Your contrast from light to dark is perfect, without much in the way of gray tones.  Yet, you still have revealed a significant amount of detail in the texture.  Your focus and DOF are dead on as well.  Well done!', '2003-06-26 19:08:39.000000', NULL, 1),
(339405, 25528, 5475, '<td valign="top">The textures and the shape of your image is appealing.  Great job with the lighting of a difficult subject.  I have a woodshop, so I have to rate this photo highly!!<br/>Good job and good luck.</td>', 'The textures and the shape of your image is appealing.  Great job with the lighting of a difficult subject.  I have a woodshop, so I have to rate this photo highly!!Good job and good luck.', '2003-06-26 19:09:47.000000', NULL, 1),
(339407, 25577, 7291, '<td valign="top">Low Key Office Art.  Two challenges in one.  Just kidding you.  I like this one a lot actually.  It takes a good eye to look at a phone and think "low key."</td>', 'Low Key Office Art.  Two challenges in one.  Just kidding you.  I like this one a lot actually.  It takes a good eye to look at a phone and think "low key."', '2003-06-26 19:15:59.000000', NULL, 1),
(339408, 24749, 7291, '<td valign="top">Great effect.  A different ghostly image besides the same one might have given a more "chilling" effect but this picture is still great.</td>', 'Great effect.  A different ghostly image besides the same one might have given a more "chilling" effect but this picture is still great.', '2003-06-26 19:22:18.000000', NULL, 1),
(339590, 25392, 312, '<td valign="top">this is a pretty nice shot, though it may be just a tad dark in the shadows. maybe a brighter tie would help accentuate what (according to the title) is part of the subject of the shot. good focus and contrast with the hands. overall a well composed shot. 7.</td>', 'this is a pretty nice shot, though it may be just a tad dark in the shadows. maybe a brighter tie would help accentuate what (according to the title) is part of the subject of the shot. good focus and contrast with the hands. overall a well composed shot. 7.', '2003-06-26 22:38:47.000000', NULL, 1),
(339593, 24878, 312, '<td valign="top">this is a very nice shot. good light, good subject. really speaks a lot. my only minor gripes would be that it''s not super sharp, which doesn''t bother me all that much but seems to maybe detract from it in this medium (i''m sure it looks better printed), and the fact that it seems a tad grainy. other than that, very well done. 9.</td>', 'this is a very nice shot. good light, good subject. really speaks a lot. my only minor gripes would be that it''s not super sharp, which doesn''t bother me all that much but seems to maybe detract from it in this medium (i''m sure it looks better printed), and the fact that it seems a tad grainy. other than that, very well done. 9.', '2003-06-26 22:40:40.000000', NULL, 1),
(339594, 25030, 312, '<td valign="top">a pretty nice shot, though not all that interesting. i''d like to see a less straigh-forward pose for this type of shot, to experiment with some of the curves that the light can bring out. also a very small crop, which doesn''t really allow me to get a good feel for how this should really look. other than that, you''ve done a good job getting good light and tones. 6.</td>', 'a pretty nice shot, though not all that interesting. i''d like to see a less straigh-forward pose for this type of shot, to experiment with some of the curves that the light can bring out. also a very small crop, which doesn''t really allow me to get a good feel for how this should really look. other than that, you''ve done a good job getting good light and tones. 6.', '2003-06-26 22:43:20.000000', NULL, 1),
(339598, 25135, 312, '<td valign="top">this is really just too dark. i''d like to see the light play more with the interesting curves and textures of the bowl. but as is, it''s mostly just dark tones and then a central reflection on the bowl. 4.</td>', 'this is really just too dark. i''d like to see the light play more with the interesting curves and textures of the bowl. but as is, it''s mostly just dark tones and then a central reflection on the bowl. 4.', '2003-06-26 22:47:23.000000', NULL, 1),
(339600, 24902, 312, '<td valign="top">good lighting to highlight nice textures and forms. this is a well done shot, but i''m not a big fan of shots that use some other form of art as their primary subject. 6.</td>', 'good lighting to highlight nice textures and forms. this is a well done shot, but i''m not a big fan of shots that use some other form of art as their primary subject. 6.', '2003-06-26 22:48:28.000000', NULL, 1),
(339602, 25450, 312, '<td valign="top">i can see where you are going with this shot, especially with the long crop, but ultimately it ends up being a little boring. good light and reflections, though. 5.</td>', 'i can see where you are going with this shot, especially with the long crop, but ultimately it ends up being a little boring. good light and reflections, though. 5.', '2003-06-26 22:49:14.000000', NULL, 1),
(339603, 25421, 312, '<td valign="top">on my monitor you can see a mismatch between the border of this image on the left and bottom and the rest of the background. it''s very distracting, but i will try not to judge your image on that. the image itself is very nice. i''m guessing it looks darker on your monitor, leaving just the side of the face highlighted, but i actually like it brighter with some of the bottom areas of hair and dark side of the face still having texture. it''s a nice shot, and good control of lighting. maybe try to adjust your monitor a bit so you can see the mismatches in color you''ve added in your photo software. 7.</td>', 'on my monitor you can see a mismatch between the border of this image on the left and bottom and the rest of the background. it''s very distracting, but i will try not to judge your image on that. the image itself is very nice. i''m guessing it looks darker on your monitor, leaving just the side of the face highlighted, but i actually like it brighter with some of the bottom areas of hair and dark side of the face still having texture. it''s a nice shot, and good control of lighting. maybe try to adjust your monitor a bit so you can see the mismatches in color you''ve added in your photo software. 7.', '2003-06-26 22:51:40.000000', NULL, 1),
(339604, 25484, 312, '<td valign="top">this is a nice shot. good control of light and nice forms. very well suited for low-key. i''ve said on a few shots this challenge that i''m not a big fan of photos where the subject is mainly another piece of art, but technically you''ve done a very good job. 7.</td>', 'this is a nice shot. good control of light and nice forms. very well suited for low-key. i''ve said on a few shots this challenge that i''m not a big fan of photos where the subject is mainly another piece of art, but technically you''ve done a very good job. 7.', '2003-06-26 22:52:48.000000', NULL, 1),
(339606, 25062, 312, '<td valign="top">this has very poor focus. i understand the limitations of lower-end cameras, but maybe if you just backed off a bit you''d have been able to get a better focus lock on the jacks. the lighting and highlights seem pretty good, and maybe with a bit more work this would be an interesting shot. 4.</td>', 'this has very poor focus. i understand the limitations of lower-end cameras, but maybe if you just backed off a bit you''d have been able to get a better focus lock on the jacks. the lighting and highlights seem pretty good, and maybe with a bit more work this would be an interesting shot. 4.', '2003-06-26 22:53:48.000000', NULL, 1),
(339607, 25495, 312, '<td valign="top">one of the interesting things about flowers are their natural state of order and aesthetic appeal, but this one really looks like it''s in bad shape. i think using a less worn subject would really allow this image to come alive. i''m also not a big fan of the background textures of the velvet. i think this would work better if the flower was alone in a darker environment with some stronger highlights and contrasts. 5.</td>', 'one of the interesting things about flowers are their natural state of order and aesthetic appeal, but this one really looks like it''s in bad shape. i think using a less worn subject would really allow this image to come alive. i''m also not a big fan of the background textures of the velvet. i think this would work better if the flower was alone in a darker environment with some stronger highlights and contrasts. 5.', '2003-06-26 22:55:47.000000', NULL, 1),
(339609, 24878, 5112, '<td valign="top">Very beautiful!  I love the light coming from the side, the hand on the glass, de folds in the shirt.  One of my favourites.</td>', 'Very beautiful!  I love the light coming from the side, the hand on the glass, de folds in the shirt.  One of my favourites.', '2003-06-26 22:57:52.000000', NULL, 1),
(339610, 25471, 312, '<td valign="top">this is a very nice image. i''m not sure i understand the title, this being an "open-to-editing" challenge, but it looks like you''ve done some work on the border, which gives the photo a more grungy feel. i like the lighting, thought it seems a tad flat. i''m thinking now that maybe the "not allowed on dpc" version includes a more liberal crop, but i think this works just fine. 8.</td>', 'this is a very nice image. i''m not sure i understand the title, this being an "open-to-editing" challenge, but it looks like you''ve done some work on the border, which gives the photo a more grungy feel. i like the lighting, thought it seems a tad flat. i''m thinking now that maybe the "not allowed on dpc" version includes a more liberal crop, but i think this works just fine. 8.', '2003-06-26 22:58:41.000000', NULL, 1),
(339611, 25429, 312, '<td valign="top">this is really well focused and framed, but i feel like the light is maybe just a little flat. i''d like to see some more contrast on the edges of the mask. 6.</td>', 'this is really well focused and framed, but i feel like the light is maybe just a little flat. i''d like to see some more contrast on the edges of the mask. 6.', '2003-06-26 22:59:28.000000', NULL, 1),
(339612, 24967, 312, '<td valign="top">this is a good effort and shows good control of your depth of field, but it feels kind of cluttered to me. perhaps without the pattern on the glass it would allow this image to be less cluttered and smoother. 5.</td>', 'this is a good effort and shows good control of your depth of field, but it feels kind of cluttered to me. perhaps without the pattern on the glass it would allow this image to be less cluttered and smoother. 5.', '2003-06-26 23:00:19.000000', NULL, 1),
(339613, 24983, 5112, '<td valign="top">Good low key entry.  The blue smoke is just beautiful.  ~8</td>', 'Good low key entry.  The blue smoke is just beautiful.  ~8', '2003-06-26 23:00:48.000000', NULL, 1),
(339615, 24995, 312, '<td valign="top">i''m not really feelin'' this one. the harsh light coming from the bulb is just too much. it''s creating cool sillhouettes in the "trees", but it''s just too bright and grabs all of your attention. also, i''d rather seem the subject down a little further toward the bottom, as it it kind of looks awkward just hanging out in the middle. 4.</td>', 'i''m not really feelin'' this one. the harsh light coming from the bulb is just too much. it''s creating cool sillhouettes in the "trees", but it''s just too bright and grabs all of your attention. also, i''d rather seem the subject down a little further toward the bottom, as it it kind of looks awkward just hanging out in the middle. 4.', '2003-06-26 23:01:56.000000', NULL, 1),
(339616, 25248, 312, '<td valign="top">good lighting, not so interesting sub ject. good framing. would rather a more subtle color in the border. 6.</td>', 'good lighting, not so interesting sub ject. good framing. would rather a more subtle color in the border. 6.', '2003-06-26 23:05:40.000000', NULL, 1),
(339617, 24855, 312, '<td valign="top">this is an interesting shot, but it''s very flat in tone.  the texture of the landscape is interesting, but i think it needs more contrast to be appealing as a photograph. 5.</td>', 'this is an interesting shot, but it''s very flat in tone.  the texture of the landscape is interesting, but i think it needs more contrast to be appealing as a photograph. 5.', '2003-06-26 23:06:32.000000', NULL, 1),
(339618, 24957, 312, '<td valign="top">slightly soft on the focus. i think a sharper focus would work better. also a tad grainy, but i think that works fine. the light is a bit flat, but you''ve got good catch lights in the eys and a nice reflection on the lips. overall a nice image. 6.</td>', 'slightly soft on the focus. i think a sharper focus would work better. also a tad grainy, but i think that works fine. the light is a bit flat, but you''ve got good catch lights in the eys and a nice reflection on the lips. overall a nice image. 6.', '2003-06-26 23:07:26.000000', NULL, 1),
(339619, 24760, 312, '<td valign="top">too grainy, which is probably a sign that you needed more light. the big fat gray border is also killing this. 4.</td>', 'too grainy, which is probably a sign that you needed more light. the big fat gray border is also killing this. 4.', '2003-06-26 23:08:06.000000', NULL, 1),
(339622, 25559, 312, '<td valign="top">i''m not sure about your decision to make this image titled to the right. it seems off balance. i love the textures in the dark areas at the top, with the handle and lid. the rest maybe has too direct light on it and isn''t allowing some of the nice textures and contours to highlight themselves. the ground here in the lower left also really detracts from this image. 5.</td>', 'i''m not sure about your decision to make this image titled to the right. it seems off balance. i love the textures in the dark areas at the top, with the handle and lid. the rest maybe has too direct light on it and isn''t allowing some of the nice textures and contours to highlight themselves. the ground here in the lower left also really detracts from this image. 5.', '2003-06-26 23:09:18.000000', NULL, 1),
(339624, 25564, 312, '<td valign="top">good lighting to highlight the textures of this sculpture, but i''m not a fan of photographs of other works of art. the big fat brown border is also hurting this image, in my opinion. also, i think the graininess of the light in the background isn''t working here, but i think some of that would work better with a less intrusive border. 6.</td>', 'good lighting to highlight the textures of this sculpture, but i''m not a fan of photographs of other works of art. the big fat brown border is also hurting this image, in my opinion. also, i think the graininess of the light in the background isn''t working here, but i think some of that would work better with a less intrusive border. 6.', '2003-06-26 23:11:01.000000', NULL, 1),
(339626, 24919, 312, '<td valign="top">i''m not sure about this as a low-key image. really it seems more like a poorly lit black and white. it''s nearly entirely gray tones, making it very flat in tone. you need more contrast to really make the subject pop. also, you haven''t got a catch light in her eyes, making her seem very dark in that area. 4.</td>', 'i''m not sure about this as a low-key image. really it seems more like a poorly lit black and white. it''s nearly entirely gray tones, making it very flat in tone. you need more contrast to really make the subject pop. also, you haven''t got a catch light in her eyes, making her seem very dark in that area. 4.', '2003-06-26 23:12:23.000000', NULL, 1),
(339629, 24888, 312, '<td valign="top">probably among the best shots of statues and such in this challenge. i''ve left comments saying that i''m not a big fan of images of other artwork on them, and i feel that here too. however, your lighting is just about perfect for this type of image. i can imagine if this were real people this image would be amazing. your stark white border is kind of hurting my eyes, though. tone that down a bit. 8.</td>', 'probably among the best shots of statues and such in this challenge. i''ve left comments saying that i''m not a big fan of images of other artwork on them, and i feel that here too. however, your lighting is just about perfect for this type of image. i can imagine if this were real people this image would be amazing. your stark white border is kind of hurting my eyes, though. tone that down a bit. 8.', '2003-06-26 23:13:48.000000', NULL, 1),
(339631, 25578, 312, '<td valign="top">this is a neat effect, but it doesn''t have a lot going for it in terms of subject. 4.</td>', 'this is a neat effect, but it doesn''t have a lot going for it in terms of subject. 4.', '2003-06-26 23:14:33.000000', NULL, 1),
(339634, 25463, 312, '<td valign="top">there is a similar shot in this challenge of a feather which i left some comments on. basically, i think that you''ve chosen a subject that is very tonally flat, and it''s not allowing any contrast to come into the image. it''s not showing us any light, which is the essence of photography. 3.</td>', 'there is a similar shot in this challenge of a feather which i left some comments on. basically, i think that you''ve chosen a subject that is very tonally flat, and it''s not allowing any contrast to come into the image. it''s not showing us any light, which is the essence of photography. 3.', '2003-06-26 23:15:37.000000', NULL, 1),
(339636, 25239, 312, '<td valign="top">this is really nice. great tones and textures, and good light, too. i think the only thing hurting this shot is that it''s a tad off-center and tilted, killing the symmetry that this place has. i think you either need to go head on or with a more extreme angle. 6.</td>', 'this is really nice. great tones and textures, and good light, too. i think the only thing hurting this shot is that it''s a tad off-center and tilted, killing the symmetry that this place has. i think you either need to go head on or with a more extreme angle. 6.', '2003-06-26 23:17:12.000000', NULL, 1),
(339639, 24893, 312, '<td valign="top">this is a nice image. the more i look the more i like it. i think the only thing detracting is the grain, which makes it seem like it''s soft on the focus. also, that red light kind of draws the eye, but there''s not much you can do about that (maybe clone it out in software). well framed and captured tho. 7.</td>', 'this is a nice image. the more i look the more i like it. i think the only thing detracting is the grain, which makes it seem like it''s soft on the focus. also, that red light kind of draws the eye, but there''s not much you can do about that (maybe clone it out in software). well framed and captured tho. 7.', '2003-06-26 23:18:27.000000', NULL, 1),
(339640, 24841, 312, '<td valign="top">i like the idea of stark contrasts here and the sky is really neat, but overall the image seems to just have too much contrast. the blacks are so black that they ultimately lose detail, and the white highlights of the sun are blown out too much. i''d like to see a large image of this, because this small crop is really making it lose a lot of detail. 5.</td>', 'i like the idea of stark contrasts here and the sky is really neat, but overall the image seems to just have too much contrast. the blacks are so black that they ultimately lose detail, and the white highlights of the sun are blown out too much. i''d like to see a large image of this, because this small crop is really making it lose a lot of detail. 5.', '2003-06-26 23:20:08.000000', NULL, 1),
(339643, 25428, 312, '<td valign="top">good depth of field, but i almost feel like the background cards are just cluttering this up. the black of the lettering on the card would probably look great when coupled with the complete black of the background, but you''ve thrown a lot of other whites and colors in there and it seems to just clutter it. 5.</td>', 'good depth of field, but i almost feel like the background cards are just cluttering this up. the black of the lettering on the card would probably look great when coupled with the complete black of the background, but you''ve thrown a lot of other whites and colors in there and it seems to just clutter it. 5.', '2003-06-26 23:21:13.000000', NULL, 1),
(339644, 25566, 312, '<td valign="top">this is nice. i think maybe the sky is just a tad flat though, and it''s kind of making me lose the subject in all that gray. i''d love to see this with the sky pushed to a whiter color to highlight the sillhouettes of the tree line and the subject. the rest of the photo has some really nice tones. 7.</td>', 'this is nice. i think maybe the sky is just a tad flat though, and it''s kind of making me lose the subject in all that gray. i''d love to see this with the sky pushed to a whiter color to highlight the sillhouettes of the tree line and the subject. the rest of the photo has some really nice tones. 7.', '2003-06-26 23:22:33.000000', NULL, 1),
(339645, 25520, 312, '<td valign="top">very nice. great light, and very nice concept. my minor gripe is the extrreme white border is kind of hurting my eyes, and the large black border is maybe just a bit too big. the image itself, stripping the borders, is very strong. 9.</td>', 'very nice. great light, and very nice concept. my minor gripe is the extrreme white border is kind of hurting my eyes, and the large black border is maybe just a bit too big. the image itself, stripping the borders, is very strong. 9.', '2003-06-26 23:23:38.000000', NULL, 1),
(339647, 25433, 312, '<td valign="top">well done. i like this. the light on the ball and the hand and the glove and the protruding knee is very nice, but i feel like the image goes tonally flat when it moves toward the right. i''d almost like to see him wearing a black t-shirt so that it really broke down to just light and highlights. overall a very strong image, though. 8.</td>', 'well done. i like this. the light on the ball and the hand and the glove and the protruding knee is very nice, but i feel like the image goes tonally flat when it moves toward the right. i''d almost like to see him wearing a black t-shirt so that it really broke down to just light and highlights. overall a very strong image, though. 8.', '2003-06-26 23:25:08.000000', NULL, 1),
(339648, 25440, 312, '<td valign="top">very dark. i think this kind of photography is all about contrast and areas of very bright light to highlight the contours and shapes of the subject. this loses all of that by using a very low, flat light which doesn''t really set the subject apart from the background. 3.</td>', 'very dark. i think this kind of photography is all about contrast and areas of very bright light to highlight the contours and shapes of the subject. this loses all of that by using a very low, flat light which doesn''t really set the subject apart from the background. 3.', '2003-06-26 23:26:08.000000', NULL, 1),
(339652, 25036, 312, '<td valign="top">i feel like there has been a very slight motion blur applied to this image and it''s kind of unsettling. pretty good lighting, though, especially in the highlights in the glasses and the texture and color the hair. 6.</td>', 'i feel like there has been a very slight motion blur applied to this image and it''s kind of unsettling. pretty good lighting, though, especially in the highlights in the glasses and the texture and color the hair. 6.', '2003-06-26 23:36:52.000000', NULL, 1),
(339654, 24946, 312, '<td valign="top">this is really nice. definitely oe of the better images of the challenge. i''m not sure i like the border that much, but i do like the idea of it. the lighting and textures on the leaves are just great tho. very well done. 9.</td>', 'this is really nice. definitely oe of the better images of the challenge. i''m not sure i like the border that much, but i do like the idea of it. the lighting and textures on the leaves are just great tho. very well done. 9.', '2003-06-26 23:37:44.000000', NULL, 1),
(339655, 24730, 312, '<td valign="top">a very boring subject with very flat tonal range. 4.</td>', 'a very boring subject with very flat tonal range. 4.', '2003-06-26 23:38:12.000000', NULL, 1),
(339656, 25259, 312, '<td valign="top">i think the background texture really kills this. the lighting is decent, and the shapes and colors of the butterfly are nice, but the texture in the background is really distracting. 5.</td>', 'i think the background texture really kills this. the lighting is decent, and the shapes and colors of the butterfly are nice, but the texture in the background is really distracting. 5.', '2003-06-26 23:40:28.000000', NULL, 1),
(339658, 25260, 312, '<td valign="top">this is just weird. the lighting on the skin is really flat. the lighting on the cutting utensil is pretty good, though. 5.</td>', 'this is just weird. the lighting on the skin is really flat. the lighting on the cutting utensil is pretty good, though. 5.', '2003-06-26 23:42:44.000000', NULL, 1),
(339662, 24749, 312, '<td valign="top">this is a pretty cool effect, but something about the shot bothers me. maybe the fact that the main subject is so centered, or that it''s tilted just a tad to the right. also, there is a small light-blemish in the lower left side that''s kind of distracting. other than that, the lighting and focus and effects are very well done. 6.</td>', 'this is a pretty cool effect, but something about the shot bothers me. maybe the fact that the main subject is so centered, or that it''s tilted just a tad to the right. also, there is a small light-blemish in the lower left side that''s kind of distracting. other than that, the lighting and focus and effects are very well done. 6.', '2003-06-26 23:48:35.000000', NULL, 1),
(339667, 25206, 312, '<td valign="top">i''m not a fan of the crazy purple effect, and it looks like you''ve pumped the levels or contrast to make this more arty. overall, i think it''s a mostly boring subject that you''ve tried, mostly unsuccessfully, to spruce up. 3.</td>', 'i''m not a fan of the crazy purple effect, and it looks like you''ve pumped the levels or contrast to make this more arty. overall, i think it''s a mostly boring subject that you''ve tried, mostly unsuccessfully, to spruce up. 3.', '2003-06-26 23:52:33.000000', NULL, 1),
(339672, 25455, 312, '<td valign="top">this is a good attempt, and i thought of doing something like this myself. unfortunately, there are some flaws with this. i''m not sure if it''s an illusion or not, but the crop makes it look a tad tilted to the right. also, the lighting seems pretty strange. maybe the focus is a bit soft, making the lighting look blurry. 5.</td>', 'this is a good attempt, and i thought of doing something like this myself. unfortunately, there are some flaws with this. i''m not sure if it''s an illusion or not, but the crop makes it look a tad tilted to the right. also, the lighting seems pretty strange. maybe the focus is a bit soft, making the lighting look blurry. 5.', '2003-06-26 23:54:12.000000', NULL, 1),
(339674, 25579, 312, '<td valign="top">the subject here is pretty dull, as is the light and tonal range. 4.</td>', 'the subject here is pretty dull, as is the light and tonal range. 4.', '2003-06-26 23:54:39.000000', NULL, 1),
(339677, 25250, 312, '<td valign="top">i think a detail of this tool without the book and with some more contrast and darker background would look a lot better. this seems a little cluttered, and also mostly filled with grays and not a lot of contrast.4.</td>', 'i think a detail of this tool without the book and with some more contrast and darker background would look a lot better. this seems a little cluttered, and also mostly filled with grays and not a lot of contrast.4.', '2003-06-26 23:55:32.000000', NULL, 1),
(339679, 25470, 312, '<td valign="top">this has some pretty interesting parts to it, but overall i think the subject is just a bit boring and the fact that it fills the frame doesn''t really help it''s case. it''s kind of in-your-face. i like the depth of field and lighting, but i think it''s just the subject/crop that detracts. 5.</td>', 'this has some pretty interesting parts to it, but overall i think the subject is just a bit boring and the fact that it fills the frame doesn''t really help it''s case. it''s kind of in-your-face. i like the depth of field and lighting, but i think it''s just the subject/crop that detracts. 5.', '2003-06-26 23:56:43.000000', NULL, 1),
(339680, 25333, 312, '<td valign="top">a very dull image, both in tonal range/contrast and in subject. 4.</td>', 'a very dull image, both in tonal range/contrast and in subject. 4.', '2003-06-26 23:57:23.000000', NULL, 1),
(339682, 24927, 312, '<td valign="top">good focus and lighting. minor things that detract are the less-than-black background elements (brown fabric or something) below the clock and the minor dings and scrapes in the clock. these things add too many distracting elements and take away from the shapes and subtletes of the clock. 5.</td>', 'good focus and lighting. minor things that detract are the less-than-black background elements (brown fabric or something) below the clock and the minor dings and scrapes in the clock. these things add too many distracting elements and take away from the shapes and subtletes of the clock. 5.', '2003-06-26 23:58:44.000000', NULL, 1),
(339685, 25547, 1031, '<td valign="top">The thin inner border is a little to close in appearance to the strings, and creates a somewhat jarring, confusing point in the lower right (maybe that''s on purpose). Not sure what I''d do about it--maybe make it 100% black and have the outer border just a touch lighter.</td>', 'The thin inner border is a little to close in appearance to the strings, and creates a somewhat jarring, confusing point in the lower right (maybe that''s on purpose). Not sure what I''d do about it--maybe make it 100% black and have the outer border just a touch lighter.', '2003-06-27 00:02:08.000000', NULL, 1),
(339697, 24841, 1031, '<td valign="top">I would try to adjust the tones a little to darken the brightest parts, and to bring out the sun rays as much as possible. Maybe you did that already. Great clouds and capture.</td>', 'I would try to adjust the tones a little to darken the brightest parts, and to bring out the sun rays as much as possible. Maybe you did that already. Great clouds and capture.', '2003-06-27 00:10:23.000000', NULL, 1),
